import json, sys
raw = json.loads(sys.stdin.read())
result = json.loads(raw['result'])
exps = result['data']['experiments']

for status in ['RUNNING', 'ANALYZING', 'QUEUED']:
    matching = {k:v for k,v in exps.items() if v.get('status') == status}
    if matching:
        print(f'\n=== {status} ({len(matching)}) ===')
        for k,v in matching.items():
            print(f'  {k}: conclusion={v.get(\"conclusion\",\"—\")}, metrics={str(v.get(\"metrics\",\"—\"))[:120]}, updated={v.get(\"updated_at\",\"—\")}')

done = sorted([(k,v) for k,v in exps.items() if v.get('status') == 'DONE'], key=lambda x: x[1].get('updated_at',''), reverse=True)[:10]
print(f'\n=== DONE (latest 10) ===')
for k,v in done:
    print(f'  {k}: conclusion={v.get(\"conclusion\",\"—\")}, metrics={str(v.get(\"metrics\",\"—\"))[:150]}')

# PREPARING with conclusion=failed or other non-null
prep = {k:v for k,v in exps.items() if v.get('status') == 'PREPARING'}
print(f'\n=== PREPARING ({len(prep)}) ===')
for k,v in list(prep.items())[:5]:
    print(f'  {k}: conclusion={v.get(\"conclusion\",\"—\")}')
